import { Lang, useText } from '@adobe-commerce/elsie/i18n';
import { useCallback, useEffect, useRef } from 'preact/compat';
import {
  GooglePay as GooglePayPaymentMethod,
  GooglePayRenderConfig,
} from '@adobe-commerce/payment-services-sdk/payment';
import { DEFAULT_LOCALE, useLocale } from '@/hooks/useLocale';
import { events } from '@adobe-commerce/event-bus';
import * as signals from '@/lib/signals';
import LocalizedError, { fromPaymentsSDKError } from '@/lib/localizedError';
import { useState } from 'preact/hooks';
import { CartModel } from '@/data/models/cart';
import { CheckoutData } from '@/data/models/checkout';
import { mapOptional, randomAlphanumericSuffix } from '@/lib/utils';

export interface GooglePayProps {
  /**
   * Called when the user clicks the Google Pay button. This callback receives a 'showPaymentSheet'
   * function as its only argument that must be called to begin the Google Pay checkout and show the
   * payment sheet.
   *
   * IMPORTANT: The 'showPaymentSheet' function MUST be called synchronously. If called
   *        ... asynchronously, calling 'showPaymentSheet' may (in some browsers) throw exception
   *        ... "PaymentRequest.show() calls after the first (per page load) require either
   *        ... transient user activation or delegated payment request capability."
   */
  onButtonClick?: (showPaymentSheet: () => void) => void;
  /**
   * Called when payment flow is successful.
   */
  onSuccess?: (result: { cartId: string }) => void;
  /**
   * Called when the payment flow was aborted due to an error.
   *
   * The function receives an object with two properties, { name: string, message: string }, containing
   * the localized error name and message. Both properties are user-facing and can be translated using
   * the "PaymentServices.GooglePay.errors" language definitions.
   */
  onError?: (localizedError: LocalizedError) => void;
  /**
   * Whether the button is hidden. Set this to true to hide the Google Pay button (default: false).
   */
  hidden?: boolean;
  /**
   * Whether the button is disabled. Set this to true to disable the Google Pay button (default: false).
   */
  disabled?: boolean;
}

const CONTAINER_CSS_CLASS = 'payment-services_google-pay-container';

export const GooglePay = ({
  onButtonClick,
  onSuccess,
  onError,
  hidden,
  disabled,
}: GooglePayProps) => {
  const sdk = signals.paymentsSDK.value?.checkout;
  const [googlePay, setGooglePay] = useState<GooglePayPaymentMethod | null>(
    null
  );
  const containerRef = useRef<HTMLDivElement>(null);
  const storeFrontLocale = useLocale();
  const initialDisabled = useRef<boolean>(!!disabled);

  // Read event payloads at call time (not at render time) so the SDK never needs to
  // re-render when cart data changes.
  const getCartDetails = useCallback(() => {
    const cartDataPayload = events.lastPayload('cart/data');
    const checkoutDataPayload =
      events.lastPayload('checkout/updated') ||
      events.lastPayload('checkout/initialized') ||
      null;
    if (!cartDataPayload || !checkoutDataPayload) {
      throw new Error(
        'Google Pay: cart/data or checkout/updated payload is not available yet.'
      );
    }
    return toPrefetchedCartDetails(cartDataPayload, checkoutDataPayload);
  }, []);

  const {
    methodNotAvailableMessage,
    methodNotLoadedMessage,
    methodLoadingMessage,
  } = useText({
    methodNotAvailableMessage: 'PaymentServices.messages.methodNotAvailable',
    methodNotLoadedMessage: 'PaymentServices.messages.methodNotLoaded',
    methodLoadingMessage: 'PaymentServices.messages.methodLoading',
  });

  useEffect(() => {
    if (!sdk?.Payment.GooglePay.isAvailable()) return;
    if (!containerRef.current) return;

    const containerId = `google-pay-${randomAlphanumericSuffix()}`;
    containerRef.current.id = containerId;

    const renderConfig: GooglePayRenderConfig = {
      container: `#${containerId}`,
      getCartId: async () => {
        const id = events.lastPayload('cart/data')?.id;
        if (!id) {
          throw new Error(
            'Google Pay: cart/data payload is not available yet.'
          );
        }
        return id;
      },
      getCartDetails,
      buttonLanguage: { locale: toGooglePayLocale(storeFrontLocale) },
      onButtonClick,
      onSuccess,
      onError: (error) => {
        if (onError === undefined) {
          console.error(error);
        } else {
          onError(fromPaymentsSDKError('GooglePay', error));
        }
      },
      disabled: initialDisabled.current,
    };

    let newGooglePayInstance: GooglePayPaymentMethod | null = null;
    sdk.Payment.GooglePay.render(renderConfig)
      .then((instance) => {
        newGooglePayInstance = instance;
        setGooglePay(newGooglePayInstance);
      })
      .catch((error) => {
        console.error('Google Pay render failed:', error);
      });

    return () => {
      if (newGooglePayInstance) {
        newGooglePayInstance.teardown();
      }
    };
  }, [
    sdk,
    getCartDetails,
    onSuccess,
    onError,
    onButtonClick,
    storeFrontLocale,
  ]);

  useEffect(() => {
    if (googlePay) {
      googlePay.setDisabled(!!disabled);
    }
  }, [googlePay, disabled]);

  const styles = {
    display: hidden ? 'none' : 'block',
  };

  if (sdk && !sdk.Payment.GooglePay.isAvailable()) {
    return (
      <div ref={containerRef} class={CONTAINER_CSS_CLASS} style={styles}>
        <div class="google-pay-error">{methodNotAvailableMessage}</div>
      </div>
    );
  }

  if (signals.status.value === 'error') {
    return (
      <div ref={containerRef} class={CONTAINER_CSS_CLASS} style={styles}>
        <div class="google-pay-error">{methodNotLoadedMessage}</div>
      </div>
    );
  }

  if (signals.status.value === 'initializing') {
    return (
      <div ref={containerRef} class={CONTAINER_CSS_CLASS} style={styles}>
        <div class="google-pay-loading">{methodLoadingMessage}</div>
      </div>
    );
  }

  return (
    <div ref={containerRef} class={CONTAINER_CSS_CLASS} style={styles}>
      {/* Google Pay button will be rendered here by the SDK */}
    </div>
  );
};

/**
 * Maps the `cart/data` and `checkout/updated` event payloads into the cart details shape
 * expected by the Payment Services SDK's Google Pay render config.
 *
 * Returns the full cart details (items, prices, billing address, shipping method) for
 * physical carts, which disables Dynamic Price Updates and displays the provided data directly.
 *
 * [1] https://developers.google.com/pay/api/web/guides/tutorial#price-updates
 */
function toPrefetchedCartDetails(cart: CartModel, checkoutData: CheckoutData) {
  const selectedShippingMethod =
    checkoutData.shippingAddresses?.[0]?.selectedShippingMethod;
  const { billingAddress } = checkoutData;

  return {
    cartItems: cart.items.map((item) => ({
      product: { name: item.name },
      quantity: item.quantity,
      prices: { row_total: item.rowTotal },
    })),
    cartPrices: {
      grand_total: cart.total.includingTax,
      grand_total_excluding_tax: cart.total.excludingTax,
      subtotal_excluding_tax: cart.subtotal.excludingTax,
      subtotal_with_discount_excluding_tax: cart.subtotal.includingDiscountOnly,
    },
    billingAddress: {
      postcode: billingAddress.postCode,
      firstname: billingAddress.firstName,
      lastname: billingAddress.lastName,
      company: billingAddress.company,
      street: billingAddress.street,
      city: billingAddress.city,
      telephone: billingAddress.telephone,
      region: mapOptional(billingAddress.region, (region) => ({
        code: region.code,
        label: region.name,
      })),
      country: billingAddress.country,
    },
    shippingMethod: mapOptional(selectedShippingMethod, (sm) => ({
      price_excl_tax: sm.amountExclTax,
      carrier_code: sm.carrier.code,
      method_code: sm.code,
    })),
  };
}

/**
 * Maps elsie locale to the format that the Payment Services SDK expects for Google Pay: a formatted
 * string consisting of an ISO-639-1 language code and an ISO-3166-1 region code, separated by a
 * hyphen (-), e.g., "en-US".
 */
function toGooglePayLocale(locale: Lang): string {
  const parts = locale.split('_'); // e.g., split "en_US" into ["en", "US"]
  if (parts.length < 2) {
    const defaultLocale = toGooglePayLocale(DEFAULT_LOCALE);
    console.warn(
      `Cannot map elsie locale "${locale}" to google pay button locale. Falling back to "${defaultLocale}".`
    );
    return defaultLocale;
  }
  return `${parts[0]}-${parts[1]}`;
}
